using YoshiWorkshop;
namespace WorkshopApp;
public sealed class RomImportForm:Form {
    readonly string root;bool working;readonly Label title=new(){Dock=DockStyle.Top,Height=60,Font=new("Segoe UI",18,FontStyle.Bold),Padding=new(20,16,10,0)};
    readonly Label explanation=new(){Dock=DockStyle.Top,Height=135,Padding=new(20,12,20,5)};readonly Label status=new(){Dock=DockStyle.Fill,Padding=new(20),AutoEllipsis=true};
    readonly ComboBox language=new(){DropDownStyle=ComboBoxStyle.DropDownList,Width=150};readonly System.Windows.Forms.Button choose=new(){Width=260,Height=42};readonly System.Windows.Forms.Button cancel=new(){Width=130,Height=42};
    bool English=>language.SelectedIndex==1;
    public RomImportForm(string pcRoot){root=pcRoot;Text="DinoTale Tornie";Width=660;Height=440;MinimumSize=new(600,410);StartPosition=FormStartPosition.CenterScreen;Font=new("Segoe UI",10);BackColor=Color.FromArgb(248,244,228);ForeColor=Color.FromArgb(30,59,56);var buttons=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=75,Padding=new(15),FlowDirection=FlowDirection.RightToLeft};buttons.Controls.Add(cancel);buttons.Controls.Add(choose);buttons.Controls.Add(language);Controls.Add(status);Controls.Add(explanation);Controls.Add(title);Controls.Add(buttons);language.Items.AddRange(new object[]{"Français","English"});language.SelectedIndex=System.Globalization.CultureInfo.CurrentUICulture.TwoLetterISOLanguageName=="fr"?0:1;language.SelectedIndexChanged+=(s,e)=>Translate();choose.Click+=async(s,e)=>await Import();cancel.Click+=(s,e)=>{DialogResult=DialogResult.Cancel;Close();};FormClosing+=(s,e)=>{if(working)e.Cancel=true;};Translate();}
    void Translate(){title.Text=English?"Prepare your game":"Préparer ton jeu";explanation.Text=English?"Choose your own original USA Yoshi’s Story ROM.\n\nThe game content is prepared locally. Your ROM is never uploaded or modified. Supported file orders: .z64, .v64 and .n64. Existing saves are preserved.":"Choisis ta propre ROM originale USA de Yoshi’s Story.\n\nLe contenu du jeu sera préparé sur ton PC. Ta ROM ne sera jamais envoyée ni modifiée. Formats acceptés : .z64, .v64 et .n64. Les sauvegardes existantes sont conservées.";choose.Text=English?"Choose my ROM…":"Choisir ma ROM…";cancel.Text=English?"Cancel":"Annuler";status.Text=English?"No ROM is included with DinoTale Tornie.":"Aucune ROM n’est incluse avec DinoTale Tornie.";}
    async Task Import(){using var picker=new OpenFileDialog{Title=English?"Choose original USA ROM":"Choisir la ROM originale USA",Filter="Nintendo64 (*.z64;*.v64;*.n64)|*.z64;*.v64;*.n64|All files (*.*)|*.*",CheckFileExists=true};if(picker.ShowDialog(this)!=DialogResult.OK)return;working=true;choose.Enabled=cancel.Enabled=language.Enabled=false;UseWaitCursor=true;status.Text=English?"Verifying the ROM and preparing local content…":"Vérification de la ROM et préparation du contenu local…";try{await Task.Run(()=>PublicRomInstall.Install(root,picker.FileName));working=false;DialogResult=DialogResult.OK;Close();}catch(Exception e){status.Text=e.Message;}finally{working=false;choose.Enabled=cancel.Enabled=language.Enabled=true;UseWaitCursor=false;}}
}
